"const fs = require('fs');
const readline = require('readline');

const logFile = 'C:/Users/user/.gemini/antigravity/brain/2313113a-c476-4aea-9e7e-55614ac9a711/.system_generated/logs/transcript.jsonl';

async function findFullView() {
  const fileStream = fs.createReadStream(logFile);
  const rl = readline.createInterface({
    input: fileStream,
    crlfDelay: Infinity
  });

  let lineCount = 0;
  for await (const line of rl) {
    lineCount++;
    if (line.includes('view_file') && line.includes('OntologyLayout.ts')) {
      const obj = JSON.parse(line);
      console.log(`Line ${lineCount}: view_file of OntologyLayout.ts`);
      console.log('  Keys:', Object.keys(obj));
      // Let's write the JSON representation of tool calls to a temporary file
      fs.writeFileSync(`scratch/step_${lineCount}_view.json`, JSON.stringify(obj, null, 2));
    }
    if (line.includes('replace_file_content') && line.includes('OntologyLayout.ts')) {
      const obj = JSON.parse(line);
      console.log(`Line ${lineCount}: replace_file_content of OntologyLayout.ts`);
      fs.writeFileSync(`scratch/step_${lineCount}_replace.json`, JSON.stringify(obj, null, 2));
    }
  }
}

findFullView();
"
